float w = 3f;
float l = 7f;
float h = 2f;

Vector3[] verts = new Vector3[]
{
    new Vector3(-w/2f, 0f, 0f),
    new Vector3( w/2f, 0f, 0f),
    new Vector3(-w/2f, h,   l),
    new Vector3( w/2f, h,   l),
};

int[] tris = new int[]
{
    0, 2, 1,
    1, 2, 3
};

Vector2[] uvs = new Vector2[]
{
    new Vector2(0f, 0f),
    new Vector2(1f, 0f),
    new Vector2(0f, 1f),
    new Vector2(1f, 1f),
};

var mesh = new Mesh();
mesh.name = "RampMesh";
mesh.vertices = verts;
mesh.triangles = tris;
mesh.uv = uvs;
mesh.RecalculateNormals();
mesh.RecalculateBounds();

var mf = go.AddComponent<MeshFilter>();
mf.sharedMesh = mesh;

var mr = go.AddComponent<MeshRenderer>();
var mat = new Material(Shader.Find("Standard"));
mat.color = new Color(0.6f, 0.6f, 0.6f);
mr.sharedMaterial = mat;

var mc = go.AddComponent<MeshCollider>();
mc.sharedMesh = mesh;

// Save mesh asset
string path = "Assets/WorldWeaverGenerated/RampMesh.asset";
System.IO.Directory.CreateDirectory("Assets/WorldWeaverGenerated");
AssetDatabase.CreateAsset(mesh, path);
AssetDatabase.SaveAssets();

var b = mesh.bounds;
return new { name = go.name, width = b.size.x, length = b.size.z, height = b.size.y, vertices = mesh.vertexCount, triangles = mesh.triangles.Length/3, meshPath = path };
"}}]}

